-- 0014_core_domain_reset.sql — additive Core Domain for F-RESET / ETAP C
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS core_users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT,role TEXT NOT NULL CHECK(role IN ('admin','designer','client','partner','service')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS auth_sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES core_users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_auth_sessions_user ON auth_sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS sales_opportunities (id TEXT PRIMARY KEY,lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,stage TEXT NOT NULL CHECK(stage IN ('qualification','consultation','proposal','negotiation','won','lost')),estimated_value_pln INTEGER,estimated_hours REAL,probability_pct INTEGER CHECK(probability_pct IS NULL OR probability_pct BETWEEN 0 AND 100),next_action TEXT,next_action_at TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_sales_stage ON sales_opportunities(stage,next_action_at);
CREATE TABLE IF NOT EXISTS core_capacity_slots (id TEXT PRIMARY KEY,starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,capacity_hours REAL NOT NULL CHECK(capacity_hours>=0),reserved_hours REAL NOT NULL DEFAULT 0 CHECK(reserved_hours>=0),notes TEXT,CHECK(ends_on>=starts_on));
CREATE TABLE IF NOT EXISTS core_projects (id TEXT PRIMARY KEY,client_user_id TEXT NOT NULL REFERENCES core_users(id),lead_id TEXT REFERENCES leads(id),name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('planned','active','waiting_client','on_hold','completed','cancelled')),location TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_core_projects_client ON core_projects(client_user_id,status);
CREATE TABLE IF NOT EXISTS core_offers (id TEXT PRIMARY KEY,lead_id TEXT NOT NULL REFERENCES leads(id),project_id TEXT REFERENCES core_projects(id),status TEXT NOT NULL CHECK(status IN ('draft','sent','viewed','accepted','rejected','expired')),currency TEXT NOT NULL DEFAULT 'PLN',total_gross INTEGER NOT NULL CHECK(total_gross>=0),valid_until TEXT,accepted_at TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT);
CREATE TABLE IF NOT EXISTS core_payments (id TEXT PRIMARY KEY,offer_id TEXT REFERENCES core_offers(id),project_id TEXT REFERENCES core_projects(id),provider TEXT NOT NULL,provider_ref TEXT,status TEXT NOT NULL CHECK(status IN ('pending','paid','failed','refunded','cancelled')),amount INTEGER NOT NULL CHECK(amount>=0),currency TEXT NOT NULL DEFAULT 'PLN',paid_at TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(provider,provider_ref));
CREATE TABLE IF NOT EXISTS core_files (id TEXT PRIMARY KEY,project_id TEXT REFERENCES core_projects(id) ON DELETE CASCADE,lead_id TEXT REFERENCES leads(id) ON DELETE CASCADE,r2_key TEXT NOT NULL UNIQUE,filename TEXT NOT NULL,kind TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('internal','client','partner')),content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>0),checksum_sha256 TEXT,created_by TEXT REFERENCES core_users(id),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),CHECK(project_id IS NOT NULL OR lead_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS domain_events (id TEXT PRIMARY KEY,name TEXT NOT NULL,aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,payload_json TEXT NOT NULL DEFAULT '{}',occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),published_at TEXT);
CREATE INDEX IF NOT EXISTS idx_domain_events_outbox ON domain_events(published_at,occurred_at);
CREATE TABLE IF NOT EXISTS automation_rules (id TEXT PRIMARY KEY,name TEXT NOT NULL,event_name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),conditions_json TEXT NOT NULL DEFAULT '{}',actions_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT);
CREATE TABLE IF NOT EXISTS idempotency_keys (key TEXT PRIMARY KEY,scope TEXT NOT NULL,request_hash TEXT NOT NULL,response_status INTEGER,response_body TEXT,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS webhook_receipts (id TEXT PRIMARY KEY,provider TEXT NOT NULL,external_event_id TEXT NOT NULL,signature_valid INTEGER NOT NULL CHECK(signature_valid IN(0,1)),payload_hash TEXT NOT NULL,received_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),processed_at TEXT,UNIQUE(provider,external_event_id));
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT,actor_user_id TEXT,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,request_id TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS idx_audit_resource ON audit_log(resource_type,resource_id,created_at);
